// ofxManifold — 3D map geometry conformance runner (round 3A-4).
//
// Reads tests/vectors/levels.vec, generated by tests/ref/reference_levels.py.
//
// Beyond matching the reference, every set of weights is checked for the
// properties that make it a 3D map, computed here from the C++ alone:
//   - they sum to one and none is negative;
//   - they REPRODUCE the point: sum of weight x (x_i, y_i, height of node i on
//     that level) is the point -- (x, y) from the floor plan, and z exactly.

#include "../src/core/ofxManifold2D.h"
#include "../src/core/ofxManifoldLevels.h"

#include <glm/vec3.hpp>

#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

using namespace ofxManifold;

namespace {

struct Tally { int pass = 0; int fail = 0; };
std::map<std::string, Tally> tallies;
std::vector<std::string> failures;
const float tolerance = 1e-5f;

void record(const std::string& cls, const std::string& name, bool ok,
            const std::string& detail) {
    Tally& t = tallies[cls];
    if (ok) ++t.pass; else {
        ++t.fail;
        failures.push_back(cls + "  " + name + "\n      " + detail);
    }
    std::cout << (ok ? "  pass  " : "  FAIL  ")
              << std::left << std::setw(10) << cls << name << "\n";
}

bool close(float a, float b) { return std::fabs(a - b) <= tolerance; }

void expectKeyword(std::istringstream& in, const char* kw) {
    std::string tok; in >> tok;
    if (tok != kw) {
        std::cerr << "malformed vector: expected " << kw << ", got " << tok
                  << "\n";
        std::exit(2);
    }
}

std::vector<std::string> splitOn(const std::string& s, char c) {
    std::vector<std::string> v;
    std::string cur;
    for (char ch : s) {
        if (ch == c) { v.push_back(cur); cur.clear(); } else cur += ch;
    }
    v.push_back(cur);
    return v;
}

struct Plan {
    std::vector<glm::vec2> pos;
    std::vector<std::vector<NodeID>> tris;
};

struct Stack {
    std::string plan;
    Levels levels;
};

std::map<std::string, Plan> plans;
std::map<std::string, Stack> stacks;

// "n@l=w ..." or "OUTSIDE"
bool readExpect(std::istringstream& in,
                std::map<std::pair<NodeID, LevelID>, float>& w) {
    std::string tok;
    bool inside = true;
    while (in >> tok) {
        if (tok == "OUTSIDE") { inside = false; continue; }
        const std::size_t at = tok.find('@'), eq = tok.find('=');
        w[{static_cast<NodeID>(std::stoul(tok.substr(0, at))),
           static_cast<LevelID>(std::stoul(tok.substr(at + 1, eq - at - 1)))}] =
            std::stof(tok.substr(eq + 1));
    }
    return inside;
}

// Compare, then check the 3D-map properties against the point (px, py, z).
bool check(const Evaluation3D& e, bool wantInside,
           const std::map<std::pair<NodeID, LevelID>, float>& want,
           const Levels& lv, const Plan& plan, float px, float py, float z,
           bool zIgnored, std::ostringstream& d) {
    if (e.inside != wantInside) {
        d << (e.inside ? "inside, expected outside" : "outside, expected inside");
        return false;
    }
    if (!wantInside) {
        if (!e.weights.empty()) { d << "outside but weights given"; return false; }
        return true;
    }
    // A weight within the tolerance of zero IS zero. On a region's edge the
    // floor plan's weight for the node across it is zero in exact arithmetic,
    // but with fused multiply-add -- every arm64 Mac -- it comes out as
    // +-1e-10. Levels passes it through, multiplied; it is neither a weight
    // that matters nor a negative one. Found by CI on macOS arm64, then
    // reproduced here with -ffp-contract=fast.
    std::map<std::pair<NodeID, LevelID>, float> got;
    for (const auto& lw : e.weights) {
        if (lw.weight < -tolerance) {
            d << "negative weight " << lw.weight << " on " << lw.node << "@"
              << lw.level;
            return false;
        }
        if (std::fabs(lw.weight) > tolerance) {
            got[{lw.node, lw.level}] += lw.weight;
        }
    }
    if (got.size() != want.size()) {
        d << got.size() << " weights, expected " << want.size();
        return false;
    }
    for (const auto& kv : want) {
        auto it = got.find(kv.first);
        if (it == got.end() || !close(it->second, kv.second)) {
            d << kv.first.first << "@" << kv.first.second << ": expected "
              << kv.second << ", got "
              << (it == got.end() ? 0.0f : it->second);
            return false;
        }
    }
    float sum = 0.0f;
    glm::vec3 p(0.0f);
    for (const auto& kv : got) {
        sum += kv.second;
        const glm::vec2 q = plan.pos[kv.first.first];
        p += kv.second * glm::vec3(q.x, q.y,
                                   lv.height(kv.first.second, kv.first.first));
    }
    if (!close(sum, 1.0f)) { d << "weights sum to " << sum; return false; }
    if (!close(p.x, px) || !close(p.y, py) || (!zIgnored && !close(p.z, z))) {
        d << "weights reproduce (" << p.x << ", " << p.y << ", " << p.z
          << "), not the point (" << px << ", " << py << ", " << z << ")";
        return false;
    }
    return true;
}

Manifold2D buildFloor(const Plan& plan) {
    Manifold2D m;
    for (std::size_t i = 0; i < plan.pos.size(); ++i) {
        m.addNode("n" + std::to_string(i), plan.pos[i]);
    }
    for (const auto& t : plan.tris) m.addRegion(t);
    return m;
}

std::map<std::string, Manifold2D> floors;

} // namespace

int main(int argc, char** argv) {
    const std::string path = argc > 1 ? argv[1] : "tests/vectors/levels.vec";
    std::ifstream f(path);
    if (!f) { std::cerr << "cannot open " << path << "\n"; return 2; }

    std::string line;
    while (std::getline(f, line)) {
        if (line.empty() || line[0] == '#') continue;
        std::istringstream in(line);
        std::string kind; in >> kind;

        if (kind == "NODES") {
            std::string name, tok; in >> name;
            Plan& p = plans[name];
            while (in >> tok) {
                const std::size_t c = tok.find(':'), k = tok.find(',');
                p.pos.emplace_back(std::stof(tok.substr(c + 1, k - c - 1)),
                                   std::stof(tok.substr(k + 1)));
            }
            continue;
        }
        if (kind == "TRIS") {
            std::string name, tok; in >> name;
            while (in >> tok) {
                std::vector<NodeID> t;
                for (const auto& s : splitOn(tok, ',')) {
                    t.push_back(static_cast<NodeID>(std::stoul(s)));
                }
                plans[name].tris.push_back(t);
            }
            floors[name] = buildFloor(plans[name]);
            continue;
        }
        if (kind == "STACK") {
            // Each operation must give exactly the result written after it.
            std::string name, pn; in >> name;
            expectKeyword(in, "NODES");
            in >> pn;
            expectKeyword(in, "OPS");
            std::string rest; std::getline(in, rest);
            Stack st; st.plan = pn;
            const std::size_t nodes = plans[pn].pos.size();
            for (std::string op : splitOn(rest, ';')) {
                std::istringstream o(op);
                std::string verb; if (!(o >> verb)) continue;
                std::string want, got;
                if (verb == "COPY") {
                    LevelID from; float base; o >> from >> base >> want;
                    std::vector<NodeID> blocked;
                    const LevelID at =
                        st.levels.copyLevel(from, base, nodes, &blocked);
                    if (at < st.levels.count() && blocked.empty()
                        && st.levels.base(at) == base) {
                        got = "=" + std::to_string(at);
                    } else {
                        got = "=REFUSED:";
                        if (blocked.empty()) got += "-";
                        for (std::size_t i = 0; i < blocked.size(); ++i) {
                            got += (i ? "," : "") + std::to_string(blocked[i]);
                        }
                    }
                } else if (verb == "RAISE") {
                    LevelID k; float dz; std::string ns;
                    o >> k >> dz >> ns >> want;
                    std::vector<NodeID> ids;
                    for (const auto& s : splitOn(ns, ',')) {
                        ids.push_back(static_cast<NodeID>(std::stoul(s)));
                    }
                    std::vector<NodeID> blocked;
                    if (st.levels.raise(k, ids, dz, &blocked)) got = "=OK";
                    else {
                        got = "=REFUSED:";
                        for (std::size_t i = 0; i < blocked.size(); ++i) {
                            got += (i ? "," : "") + std::to_string(blocked[i]);
                        }
                    }
                } else if (verb == "SET") {
                    LevelID k; NodeID n; float h; o >> k >> n >> h >> want;
                    got = st.levels.setHeight(k, n, h) ? "=OK" : "=REFUSED";
                } else if (verb == "REMOVE") {
                    LevelID k; o >> k >> want;
                    got = st.levels.removeLevel(k) ? "=OK" : "=REFUSED";
                }
                if (got != want) {
                    record("ANALYTIC", "stack_" + name + "_" + verb, false,
                           "'" + op + "' gave " + got);
                }
            }
            stacks[name] = st;
            continue;
        }

        std::string name, cls; in >> name >> cls;
        std::ostringstream d;

        if (kind == "HEIGHTS") {
            // Every node's height on every level, and the level count.
            std::string sn; in >> sn;
            const Levels& lv = stacks[sn].levels;
            std::vector<std::vector<float>> want;
            std::string tok;
            while (in >> tok) {
                if (tok[0] == 'L') { want.emplace_back(); continue; }
                for (const auto& s : splitOn(tok, ',')) {
                    want.back().push_back(std::stof(s));
                }
            }
            bool ok = lv.count() == want.size();
            if (!ok) d << lv.count() << " levels, expected " << want.size();
            for (LevelID k = 0; ok && k < want.size(); ++k) {
                for (NodeID i = 0; ok && i < want[k].size(); ++i) {
                    if (!close(lv.height(k, i), want[k][i])) {
                        ok = false;
                        d << "node " << i << " on level " << k << " at "
                          << lv.height(k, i) << ", expected " << want[k][i];
                    }
                }
            }
            record(cls, name, ok, d.str());

        } else if (kind == "EVAL3") {
            std::string sn; in >> sn;
            expectKeyword(in, "W");
            Evaluation floor;
            floor.inside = true;
            std::string tok;
            while (in >> tok && tok != "Z") {
                const std::size_t eq = tok.find('=');
                floor.weights.push_back(WeightedNode{
                    static_cast<NodeID>(std::stoul(tok.substr(0, eq))),
                    std::stof(tok.substr(eq + 1))});
            }
            float z; in >> z;
            expectKeyword(in, "EXPECT");
            std::map<std::pair<NodeID, LevelID>, float> want;
            const bool inside = readExpect(in, want);
            const Stack& st = stacks[sn];
            const Plan& plan = plans[st.plan];
            float px = 0.0f, py = 0.0f;
            for (const auto& wn : floor.weights) {
                px += wn.weight * plan.pos[wn.id].x;
                py += wn.weight * plan.pos[wn.id].y;
            }
            const Evaluation3D e = st.levels.evaluate(floor, z);
            const bool ok = check(e, inside, want, st.levels, plan, px, py, z,
                                  st.levels.count() == 1, d);
            record(cls, name, ok, d.str());

        } else if (kind == "EVALXYZ") {
            // The whole path: the C++ floor plan evaluates (x, y) itself.
            std::string sn, fp; in >> sn >> fp;
            expectKeyword(in, "P");
            float x, y, z; in >> x >> y >> z;
            expectKeyword(in, "EXPECT");
            std::map<std::pair<NodeID, LevelID>, float> want;
            const bool inside = readExpect(in, want);
            const std::string plan = fp == "SQUARE" ? "square" : fp;
            const Stack& st = stacks[sn];
            const Evaluation floor = floors[plan].evaluate(glm::vec2(x, y));
            const Evaluation3D e = st.levels.evaluate(floor, z);
            const bool ok = check(e, inside, want, st.levels, plans[plan],
                                  x, y, z, st.levels.count() == 1, d);
            record(cls, name, ok, d.str());

        } else if (kind == "CONT") {
            // No step along a straight sweep may change any weight by more
            // than the bound; every step must be inside and reproduce its
            // point.
            std::string sn, fp; in >> sn >> fp;
            const std::string plan = fp == "SQUARE" ? "square" : fp;
            expectKeyword(in, "FROM");
            float ax, ay, az; in >> ax >> ay >> az;
            expectKeyword(in, "TO");
            float bx, by, bz; in >> bx >> by >> bz;
            expectKeyword(in, "STEPS");
            int steps; in >> steps;
            expectKeyword(in, "MAXSTEP");
            float bound; in >> bound;
            const Stack& st = stacks[sn];
            std::map<std::pair<NodeID, LevelID>, float> prev;
            float worst = 0.0f;
            bool ok = true;
            for (int s = 0; ok && s <= steps; ++s) {
                const float u = static_cast<float>(s) / steps;
                const float x = ax + (bx - ax) * u, y = ay + (by - ay) * u;
                const float z = az + (bz - az) * u;
                const Evaluation3D e = st.levels.evaluate(
                    floors[plan].evaluate(glm::vec2(x, y)), z);
                std::map<std::pair<NodeID, LevelID>, float> now;
                // Weights within the tolerance of zero are dropped, as
                // check() drops them: on the square's diagonal the floor plan
                // reports the node across the edge at 0, or +-1e-10 with
                // fused multiply-add.
                for (const auto& lw : e.weights) {
                    if (std::fabs(lw.weight) > tolerance) {
                        now[{lw.node, lw.level}] += lw.weight;
                    }
                }
                std::ostringstream dd;
                if (!check(e, true, now, st.levels, plans[plan], x, y, z,
                           false, dd)) {
                    ok = false; d << "step " << s << ": " << dd.str();
                    break;
                }
                if (s > 0) {
                    auto keys = now;
                    for (const auto& kv : prev) keys[kv.first];
                    for (const auto& kv : keys) {
                        const float a = prev.count(kv.first) ? prev[kv.first] : 0.0f;
                        const float b = now.count(kv.first) ? now[kv.first] : 0.0f;
                        worst = std::max(worst, std::fabs(b - a));
                    }
                }
                prev = now;
            }
            if (ok && worst > bound) {
                ok = false;
                d << "a step changed a weight by " << worst << ", bound "
                  << bound;
            }
            record(cls, name, ok, d.str());

        } else if (kind == "NEWNODE") {
            // A node the levels have never heard of: each level's start.
            std::string sn; in >> sn;
            expectKeyword(in, "NODE");
            NodeID n; in >> n;
            expectKeyword(in, "HEIGHTS");
            std::string hs; in >> hs;
            const auto want = splitOn(hs, ',');
            const Levels& lv = stacks[sn].levels;
            bool ok = lv.count() == want.size();
            for (LevelID k = 0; ok && k < want.size(); ++k) {
                if (!close(lv.height(k, n), std::stof(want[k]))
                    || lv.bent(k, n)) {
                    ok = false; d << "level " << k << ": " << lv.height(k, n);
                }
            }
            record(cls, name, ok, d.str());

        } else if (kind == "REMAP3") {
            std::string sn; in >> sn;
            expectKeyword(in, "TABLE");
            std::vector<NodeID> table;
            std::string tok;
            while (in >> tok && tok[0] != 'L') {
                const long v = std::stol(tok);
                table.push_back(v < 0 ? InvalidNode : static_cast<NodeID>(v));
            }
            Levels lv = stacks[sn].levels;
            lv.remapNodes(table);
            std::vector<std::vector<float>> want(1);
            while (in >> tok) {
                if (tok[0] == 'L') { want.emplace_back(); continue; }
                for (const auto& s : splitOn(tok, ',')) {
                    want.back().push_back(std::stof(s));
                }
            }
            bool ok = lv.count() == want.size();
            if (!ok) d << lv.count() << " levels";
            for (LevelID k = 0; ok && k < want.size(); ++k) {
                for (NodeID i = 0; ok && i < want[k].size(); ++i) {
                    if (!close(lv.height(k, i), want[k][i])) {
                        ok = false;
                        d << "node " << i << " on level " << k << " at "
                          << lv.height(k, i) << ", expected " << want[k][i];
                    }
                }
            }
            record(cls, name, ok, d.str());

        } else {
            std::cerr << "unknown record type: " << kind << "\n";
            return 2;
        }
    }

    int fail = 0, pass = 0;
    for (const auto& kv : tallies) { pass += kv.second.pass; fail += kv.second.fail; }
    if (!failures.empty()) {
        std::cout << "\nfailures:\n";
        for (const auto& s : failures) std::cout << "  " << s << "\n";
    }
    std::cout << "\n" << pass << "/" << (pass + fail) << "  "
              << (fail ? "RED" : "GREEN") << "\n";
    return fail ? 1 : 0;
}
